94	// renderSceneSVG produces a self-contained SVG string for the given scene.
95	// `bgMode` is "transparent" (default), "light", or "dark".
96	func renderSceneSVG(scene svgScene, bgMode string) string {
97		const pad = 20.0
98		if len(scene.Elements) == 0 {
99			return `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="40" viewBox="0 0 100 40"><text x="50" y="25" text-anchor="middle" font-family="sans-serif" font-size="14" fill="#9ca3af">empty drawing</text></svg>`
100		}
101	
102		minX, minY := math.Inf(1), math.Inf(1)
103		maxX, maxY := math.Inf(-1), math.Inf(-1)
104		for _, e := range scene.Elements {
105			bx, by, bw, bh := elementBBox(e)
106			if bx < minX {
107				minX = bx
108			}
109			if by < minY {
110				minY = by
111			}
112			if bx+bw > maxX {
113				maxX = bx + bw
114			}
115			if by+bh > maxY {
116				maxY = by + bh
117			}
118		}
119		w := (maxX - minX) + pad*2
120		h := (maxY - minY) + pad*2
121		ox := -minX + pad
122		oy := -minY + pad
123	
124		var b strings.Builder
125		fmt.Fprintf(&b, `<svg xmlns="http://www.w3.org/2000/svg" width="%s" height="%s" viewBox="0 0 %s %s">`,
126			f(w), f(h), f(w), f(h))
127		b.WriteByte('\n')
128		switch strings.ToLower(bgMode) {
129		case "light":
130			fmt.Fprintf(&b, `<rect width="%s" height="%s" fill="#ffffff"/>`, f(w), f(h))
131			b.WriteByte('\n')
132		case "dark":
133			fmt.Fprintf(&b, `<rect width="%s" height="%s" fill="#1a1a2e"/>`, f(w), f(h))
134			b.WriteByte('\n')
135		}
136		fmt.Fprintf(&b, `<g transform="translate(%s,%s)">`, f(ox), f(oy))
137		b.WriteByte('\n')
138	
139		for _, el := range scene.Elements {
140			writeElementSVG(&b, el)
141		}
142	
143		b.WriteString("</g>\n</svg>\n")
144		return b.String()
145	}
