147	func elementBBox(el svgElement) (x, y, w, h float64) {
148		switch el.Type {
149		case "rect", "diamond", "ellipse", "text", "image":
150			return minf(el.X, el.X+el.W), minf(el.Y, el.Y+el.H), math.Abs(el.W), math.Abs(el.H)
151		case "line", "arrow":
152			if len(el.Pts) > 0 {
153				xs := []float64{}
154				ys := []float64{}
155				for _, p := range el.Pts {
156					xs = append(xs, p.X)
157					ys = append(ys, p.Y)
158				}
159				if el.Cp != nil {
160					xs = append(xs, el.Cp.X)
161					ys = append(ys, el.Cp.Y)
162				}
163				mx, my := xs[0], ys[0]
164				mxx, mxy := xs[0], ys[0]
165				for i := range xs {
166					if xs[i] < mx {
167						mx = xs[i]
168					}
169					if xs[i] > mxx {
170						mxx = xs[i]
171					}
172					if ys[i] < my {
173						my = ys[i]
174					}
175					if ys[i] > mxy {
176						mxy = ys[i]
177					}
178				}
179				return mx, my, mxx - mx, mxy - my
180			}
181			mx := minf(el.X, el.X2)
182			my := minf(el.Y, el.Y2)
183			w := math.Abs(el.X2 - el.X)
184			h := math.Abs(el.Y2 - el.Y)
185			if el.Cp != nil {
186				if el.Cp.X < mx {
187					w += mx - el.Cp.X
188					mx = el.Cp.X
189				}
190				if el.Cp.X > mx+w {
191					w = el.Cp.X - mx
192				}
193				if el.Cp.Y < my {
194					h += my - el.Cp.Y
195					my = el.Cp.Y
196				}
197				if el.Cp.Y > my+h {
198					h = el.Cp.Y - my
199				}
200			}
201			return mx, my, w, h
202		case "pencil":
203			if len(el.Pts) == 0 {
204				return 0, 0, 0, 0
205			}
206			mx, my := el.Pts[0].X, el.Pts[0].Y
207			mxx, mxy := mx, my
208			for _, p := range el.Pts {
209				if p.X < mx {
210					mx = p.X
211				}
212				if p.X > mxx {
213					mxx = p.X
214				}
215				if p.Y < my {
216					my = p.Y
217				}
218				if p.Y > mxy {
219					mxy = p.Y
220				}
221			}
222			return mx, my, mxx - mx, mxy - my
223		}
224		return 0, 0, 0, 0
225	}
