402	// fontCSS returns a font-family stack using single quotes so it can be
403	// dropped straight into an SVG attribute without escaping.
404	func fontCSS(ff string) string {
405		switch ff {
406		case "hand":
407			return `'Virgil', 'Segoe Print', 'Comic Sans MS', cursive`
408		case "serif":
409			return `'Georgia', 'Times New Roman', serif`
410		case "mono":
411			return `'SFMono-Regular', 'Consolas', 'Liberation Mono', monospace`
412		default:
413			return `-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif`
414		}
415	}
