  // ── Tool state ────────────────────────────────────────────────────────────
  let activeTool = "select";
  let strokeColor = "#1e1e2e";
  let fillColor = "transparent";
  let strokeWidth = 2;
  let fontSize = 16;
  let fontFamily = "hand";       // "hand" | "sans-serif" | "mono" | "serif"
  let textAlign = "center";     // "left" | "center" | "right"
  let strokeStyle = "solid";   // "solid" | "dashed" | "dotted"
  let fillStyle = "hachure";   // "hachure" | "cross-hatch" | "solid"
  let roughness = 0;           // 0=architect, 1=artist, 2=cartoonist
  let roundness = "sharp";     // "sharp" | "round"
  let opacity = 100;           // 0-100

  // ── Interaction state ────────────────────────────────────────────────────
  let drawing = false;
  let currentEl = null;
  let startX = 0, startY = 0;
  let pencilPoints = [];
  let panning = false;
  let panStart = { x: 0, y: 0, vpx: 0, vpy: 0 };
  let selectedIds = new Set();
  let dragOffset = { x: 0, y: 0 };
  let isDragging = false;
  let isRotating = false;
  let rotateStartAngle = 0;
  let rotateOriginalAngle = 0;
  let isResizing = false;
  let resizeHandle = "";       // "nw","ne","sw","se" for shapes; "start","end" for lines
  let resizeOriginal = null;   // snapshot of element before resize
  let groupTransform = null;   // { mode, handle, bbox, center, originals:Map<id,el> }
  let textInput = null;

