    "serif":      '"Georgia", "Times New Roman", serif',
    "mono":       '"SFMono-Regular", "Consolas", "Liberation Mono", monospace',
    "hand":       '"Virgil", "Segoe Print", "Comic Sans MS", cursive',
  };
  function fontCSS(ff) { return FONT_CSS[ff] || FONT_CSS["sans-serif"]; }

