import { useEffect, useState, useCallback, useRef } from 'react'
import { createRoot } from 'react-dom/client'
import { useNavigate, Link } from 'react-router-dom'
import { WikiPage, WikiPageVersion, WikiPageVersionWithContent, WikiAnnotation, AnnotationColor, AnnotationComment, apiClient } from '../lib/api'
import WikiAnnotationSidebar from './WikiAnnotationSidebar'
import FigmaEmbed from './FigmaEmbed'
import { useAuth } from '../state/AuthContext'
import SearchSelect from './ui/SearchSelect'
import ImagePickerModal from './ImagePickerModal'
import * as Y from 'yjs'
import { WebsocketProvider } from 'y-websocket'
import {
  unescapeHtml,
  buildImageMarkup,
  findImagesInContent,
  detectImageSize,
  findDrawsInContent,
  mapYjsStatus,
  findDrawShortcodeAtPosition,
  shouldSaveContent,
  getSaveStatusColor,
  getSaveStatusText,
  getSaveStatusTextColor,
  buildDrawShortcode,
  buildFigmaShortcode,
  insertMarkupAtCursor,
  clearSavedStatus,
  insertAtCursorPure,
  insertLinePure,
  escapeRegExp,
  fetchDrawings,
  createDrawing,
  renameDrawing,
  deleteDrawing,
  deleteDrawings,
  fetchPreview,
} from './WikiEditor.helpers'
import type { ImageInfo, DrawInfo, DrawItem, SyncState, SaveStatus } from './WikiEditor.helpers'

// Use relative URL in production, or VITE_API_URL for dev override
const API_BASE = import.meta.env.VITE_API_URL || (import.meta.env.PROD ? '' : 'http://localhost:8080')
const PREVIEW_ENDPOINT = `${API_BASE}/api/wiki/preview`
const PREVIEW_DEBOUNCE_MS = 350

interface WikiEditorProps {
  page: WikiPage
  annotations?: WikiAnnotation[]
  selectedAnnotationId?: number | null
  showAnnotationHighlights?: boolean
  onAnnotationCreate?: (info: { startOffset: number; endOffset: number; selectedText: string; color: AnnotationColor }) => void
  onAnnotationClick?: (annotationId: number) => void
  // Sidebar callbacks threaded through for fullscreen support
  onAnnotationUpdate?: (annotation: WikiAnnotation) => void
  onAnnotationDelete?: (annotationId: number) => void
  onCommentCreate?: (annotationId: number, comment: AnnotationComment) => void
  onCommentUpdate?: (comment: AnnotationComment) => void
  onCommentDelete?: (annotationId: number, commentId: number) => void
  showResolved?: boolean
  onToggleShowResolved?: () => void
}

// Annotation highlight helpers are provided by window.GoWikiAnnotations (go-wiki package).
// See web/src/lib/goWikiAnnotations.d.ts for types.

// ── Toolbar helpers ──────────────────────────────────────────────

function insertAtCursor(
  textarea: HTMLTextAreaElement,
  before: string,
  after: string,
  content: string,
  setContent: (c: string) => void,
  syncToYjs: (c: string) => void,
  isDirtyRef?: React.MutableRefObject<boolean>,
) {
  const { newContent, cursorStart, cursorEnd } = insertAtCursorPure(
    content, textarea.selectionStart, textarea.selectionEnd, before, after,
  )
  setContent(newContent)
  syncToYjs(newContent)
  if (isDirtyRef) isDirtyRef.current = true

  setTimeout(() => {
    textarea.focus()
    textarea.selectionStart = cursorStart
    textarea.selectionEnd = cursorEnd
  }, 0)
}

function insertLine(
  textarea: HTMLTextAreaElement,
  prefix: string,
  content: string,
  setContent: (c: string) => void,
  syncToYjs: (c: string) => void,
  isDirtyRef?: React.MutableRefObject<boolean>,
) {
  const { newContent, cursorStart } = insertLinePure(content, textarea.selectionStart, prefix)
  setContent(newContent)
  syncToYjs(newContent)
  if (isDirtyRef) isDirtyRef.current = true

  setTimeout(() => {
    textarea.focus()
    textarea.selectionStart = textarea.selectionEnd = cursorStart
  }, 0)
}

// ── Toolbar button definitions ───────────────────────────────────

interface ToolbarAction {
  label: string
  icon: string
