function PreviewContent({ previewHTML, content, previewRef }: Readonly<{
  previewHTML: string
  content: string
  previewRef: React.Ref<HTMLDivElement>
}>) {
  const innerRef = useRef<HTMLDivElement>(null)

  // Render KaTeX math after preview HTML is inserted into DOM
  useEffect(() => {
    if (!previewHTML || !innerRef.current) return
    // Load KaTeX CSS if not already present
    if (!document.querySelector('link[href*="katex"]')) {
      const link = document.createElement('link')
      link.rel = 'stylesheet'
      link.href = 'https://cdn.jsdelivr.net/npm/katex@0.16.22/dist/katex.min.css'
      document.head.appendChild(link)
    }
    // Load auto-render script and render math
    const renderMath = () => {
      const win = window as unknown as Record<string, unknown>
      if (typeof win.renderMathInElement === 'function') {
        (win.renderMathInElement as (el: HTMLElement, opts: object) => void)(innerRef.current!, {
          delimiters: [
            { left: '$$', right: '$$', display: true },
            { left: '$', right: '$', display: false },
          ],
          throwOnError: false,
        })
      }
    }
    if ((window as unknown as Record<string, unknown>).renderMathInElement) {
      renderMath()
    } else {
      const script = document.createElement('script')
      script.src = 'https://cdn.jsdelivr.net/npm/katex@0.16.22/dist/contrib/auto-render.min.js'
      script.onload = renderMath
      document.head.appendChild(script)
    }
  }, [previewHTML])

  // Merge refs: internal + forwarded
  const setRefs = useCallback((el: HTMLDivElement | null) => {
    (innerRef as React.MutableRefObject<HTMLDivElement | null>).current = el
    if (typeof previewRef === 'function') previewRef(el)
    else if (previewRef) (previewRef as React.MutableRefObject<HTMLDivElement | null>).current = el
  }, [previewRef])

  if (previewHTML) {
    return (
      <div
        ref={setRefs}
        className="prose prose-invert max-w-none"
        dangerouslySetInnerHTML={{ __html: previewHTML }}
      />
    )
  }
  if (content.trim()) {
    return (
      <div className="flex items-center justify-center h-full text-dark-text-tertiary">
        <p className="text-sm">Loading preview...</p>
      </div>
    )
  }
  return (
    <div className="flex items-center justify-center h-full text-dark-text-tertiary">
      <div className="text-center">
        <svg className="w-16 h-16 mx-auto mb-4 text-dark-text-tertiary/50" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
        </svg>
        <p className="text-lg">No content to preview</p>
        <p className="text-sm mt-2">Switch to Edit mode to start writing</p>
      </div>
    </div>
  )
}

